// Вместо:
const coords = [10, 20, 30];
const x = coords[0];
const y = coords[1];

// Пишем:
const [x, y] = [10, 20, 30];
console.log(x);  // 10
console.log(y);  // 20

// Третий элемент игнорируется — мы объявили только две переменные

// Можно пропустить элемент:
const [first, , third] = [10, 20, 30];
console.log(first);  // 10
console.log(third);  // 30 — пропустили индекс 1

let a = 1;
let b = 2;

// Старый способ — с временной переменной:
let temp = a;
a = b;
b = temp;

// Новый способ — деструктуризацией:
[a, b] = [b, a];
console.log(a, b);  // 2 1

// Работает потому что правая часть [b, a] вычисляется ДО присвоения

const user = {
  name: "Alice",
  age: 25,
  city: "Moscow"
};

// Имена переменных = имена ключей
const { name, age } = user;
console.log(name);  // Alice
console.log(age);   // 25

// Порядок НЕ важен — всё равно будет верно:
const { age, name } = user;
console.log(name);  // Alice
console.log(age);   // 25

// Лишние свойства просто игнорируются — city не распакован

