const product = {
  productName: "Laptop",
  productPrice: 999
};

// Переименовываем при деструктуризации:
const {
  productName: name,   // productName → name
  productPrice: price  // productPrice → price
} = product;

console.log(name);   // Laptop
console.log(price);  // 999

const config = {
  host: "localhost"
  // port отсутствует!
};

// port не найден → используем значение по умолчанию
const { host, port = 3000 } = config;
console.log(host);  // localhost
console.log(port);  // 3000 — из defaults

// Для массива тоже работает:
const [a, b = 99] = [1];
console.log(b);     // 99 — второго элемента нет

// ВАЖНО: default НЕ срабатывает для null!
const obj = { count: null };
const { count = 10 } = obj;
console.log(count); // null — а не 10!

// Опасно:
const result = null;
// const { value } = result;  // TypeError: Cannot destructure property...

// Безопасно — fallback на пустой объект:
const { value } = result || {};
console.log(value);  // undefined — без ошибки

// Или проверка перед деструктуризацией:
if (result) {
  const { value } = result;
}

// Функция принимает ОБЪЕКТ и сразу распаковывает нужные поля
function greet({ name, age = 0 }) {
  console.log(`${name}, ${age} лет`);
}

greet({ name: "Eve", age: 30 });  // Eve, 30 лет
greet({ name: "Tom" });           // Tom, 0 лет — age по умолчанию

// С массивом:
function printPoint([x, y]) {
  console.log(`(${x}, ${y})`);
}
printPoint([3, 4]);  // (3, 4)

const data = {
  user: {
    name: "Bob",
    address: {
      city: "SPb",
      zip: "190000"
    }
  }
};

// Вложенная деструктуризация:
const { user: { address: { city } } } = data;
console.log(city);  // SPb

// Эквивалент без деструктуризации:
// const city = data.user.address.city;

